import Model from 'flarum/common/Model';
export default class Participant extends Model {
  foundCount() {
    return Model.attribute('foundCount').call(this);
  }
  firstFoundAt() {
    return Model.attribute('firstFoundAt', Model.transformDate).call(this);
  }
  lastFoundAt() {
    return Model.attribute('lastFoundAt', Model.transformDate).call(this);
  }
  completedAt() {
    return Model.attribute('completedAt', Model.transformDate).call(this);
  }
  position() {
    return Model.attribute('position').call(this);
  }
  encounterCount() {
    return Model.attribute('encounterCount').call(this);
  }
  averageClaimMs() {
    return Model.attribute('averageClaimMs').call(this);
  }
  fastClaimFlag() {
    return Model.attribute('fastClaimFlag').call(this);
  }
  user() {
    return Model.hasOne('user').call(this);
  }
}
flarum.reg.add('fof-scavenger-hunt', 'common/models/Participant', Participant);