import app from 'flarum/forum/app';
/**
 * Core alerts stay until dismissed; confirmations shouldn't, so these clear themselves.
 */
export default function toast(message, ms) {
  if (ms === void 0) {
    ms = 4000;
  }
  const id = app.alerts.show({
    type: 'success'
  }, message);
  setTimeout(() => app.alerts.dismiss(id), ms);
}
flarum.reg.add('fof-scavenger-hunt', 'forum/utils/toast', toast);