import Model from 'flarum/common/Model';
export default class Hunt extends Model {
  title() {
    return Model.attribute('title').call(this);
  }
  slug() {
    return Model.attribute('slug').call(this);
  }
  description() {
    return Model.attribute('description').call(this);
  }
  startsAt() {
    return Model.attribute('startsAt', Model.transformDate).call(this);
  }
  endsAt() {
    return Model.attribute('endsAt', Model.transformDate).call(this);
  }
  isActive() {
    return Model.attribute('isActive').call(this);
  }
  imageUrl() {
    return Model.attribute('imageUrl').call(this);
  }
  completedImageUrl() {
    return Model.attribute('completedImageUrl').call(this);
  }
  partCount() {
    return Model.attribute('partCount').call(this);
  }
  finisherCount() {
    return Model.attribute('finisherCount').call(this);
  }

  /**
   * Only present for Hunt managers.
   */
  participantCount() {
    return Model.attribute('participantCount').call(this);
  }
  foundCount() {
    return Model.attribute('foundCount').call(this);
  }
  completedAt() {
    return Model.attribute('completedAt', Model.transformDate).call(this);
  }
  isEnabled() {
    return Model.attribute('isEnabled').call(this);
  }
  guestsCanSee() {
    return Model.attribute('guestsCanSee').call(this);
  }
  image() {
    return Model.attribute('image').call(this);
  }
  completedImage() {
    return Model.attribute('completedImage').call(this);
  }
  template() {
    return Model.attribute('template').call(this);
  }
  finishingPosition() {
    return Model.attribute('finishingPosition').call(this);
  }
  rewardMessage() {
    return Model.attribute('rewardMessage').call(this);
  }

  /**
   * Only present for Hunt managers and for members who have earned the Completion.
   */
  rewardMessageHtml() {
    return Model.attribute('rewardMessageHtml').call(this);
  }
  rewardGroup() {
    return Model.hasOne('rewardGroup').call(this);
  }
  parts() {
    return Model.hasMany('parts').call(this);
  }
}
flarum.reg.add('fof-scavenger-hunt', 'common/models/Hunt', Hunt);