import app from 'flarum/forum/app';
import { extend, override } from 'flarum/common/extend';
import Page from 'flarum/common/components/Page';
import LinkButton from 'flarum/common/components/LinkButton';
import Footer from 'flarum/forum/components/Footer';
import HeaderSecondary from 'flarum/forum/components/HeaderSecondary';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import SessionDropdown from 'flarum/forum/components/SessionDropdown';
import Button from 'flarum/common/components/Button';
import HidingSpot from './components/HidingSpot';
import HuntIndicator from './components/HuntIndicator';
import { encounters, lookUpWhenDrawerOpens } from './states/EncounterState';
import { placement } from './states/placement';
import { activeHunts, canManageHunts } from './utils/activeHunts';
export { default as extend } from './extend';
app.initializers.add('fof-scavenger-hunt', () => {
  // Every page change starts a fresh page view: spots are reported again and old Encounters dropped.
  extend(Page.prototype, 'oninit', function () {
    encounters.pageChanged(app.current.get('routeName') ?? '', m.route.param() ?? {});
  });
  lookUpWhenDrawerOpens();
  extend(HeaderSecondary.prototype, 'items', function (items) {
    if (activeHunts().length && app.forum.attribute('fof-scavenger-hunt.showHeaderIndicator')) {
      items.add('scavengerHuntIndicator', m(HuntIndicator, null), 15);
    }
    items.add('scavengerHuntSpot', m(HidingSpot, {
      spot: "page.header"
    }), 14);
  });
  extend(IndexSidebar.prototype, 'items', function (items) {
    items.add('scavengerHuntSpot', m(HidingSpot, {
      spot: "page.sidebar"
    }), -100);
  });
  extend(IndexSidebar.prototype, 'navItems', function (items) {
    if (canManageHunts()) {
      items.add('scavengerHuntDashboard', m(LinkButton, {
        icon: "fas fa-binoculars",
        href: app.route('fof-scavenger-hunt.dashboard')
      }, app.translator.trans('fof-scavenger-hunt.forum.dashboard.nav')), -50);
    }
  });
  extend(SessionDropdown.prototype, 'items', function (items) {
    if (canManageHunts()) {
      items.add('scavengerHuntDashboard', m(LinkButton, {
        icon: "fas fa-binoculars",
        href: app.route('fof-scavenger-hunt.dashboard')
      }, app.translator.trans('fof-scavenger-hunt.forum.dashboard.nav')), 75);
      items.add('scavengerHuntPlace', placement.active ? m(Button, {
        icon: "fas fa-times",
        onclick: () => placement.stop()
      }, app.translator.trans('fof-scavenger-hunt.forum.placement_mode.stop')) : m(Button, {
        icon: "fas fa-map-pin",
        onclick: () => placement.start()
      }, app.translator.trans('fof-scavenger-hunt.forum.placement_mode.start')), 74);
    }
  });

  // Precise spots. String-path extends also cover modules a future core moves into a lazy chunk.
  extend('flarum/forum/components/DiscussionHero', 'items', function (items) {
    items.add('scavengerHuntSpot', m(HidingSpot, {
      spot: "discussion.hero",
      context: ['discussion', Number(this.attrs.discussion.id())]
    }), -100);
  });
  extend('flarum/forum/components/CommentPost', 'content', function (content) {
    content.push(m(HidingSpot, {
      spot: "post.body-end",
      className: "HidingSpot-postBody",
      context: ['post', Number(this.attrs.post.id())]
    }));
  });

  // CommentPost, not Post: once any extension extends CommentPost's inherited footerItems, CommentPost
  // holds its own copy wrapping Post's original, and a later extend of Post never reaches comment posts.
  extend('flarum/forum/components/CommentPost', 'footerItems', function (items) {
    items.add('scavengerHuntSpot', m(HidingSpot, {
      spot: "post.footer",
      context: ['post', Number(this.attrs.post.id())]
    }), -100);
  });
  extend('flarum/forum/components/DiscussionListItem', 'contentItems', function (items) {
    items.add('scavengerHuntSpot', m(HidingSpot, {
      spot: "discussionList.item",
      context: ['discussion', Number(this.attrs.discussion.id())]
    }), 60);
  });
  extend('flarum/forum/components/UserCard', 'infoItems', function (items) {
    items.add('scavengerHuntSpot', m(HidingSpot, {
      spot: "user.card",
      context: ['user', Number(this.attrs.user.id())]
    }), -100);
  });
  extend('flarum/forum/components/UserPage', 'sidebarItems', function (items) {
    if (this.user) {
      items.add('scavengerHuntSpot', m(HidingSpot, {
        spot: "user.sidebar",
        context: ['user', Number(this.user.id())]
      }), -100);
    }
  });
  if (app.initializers.has('flarum-tags')) {
    // TagsPage renders each tile directly, with no ItemList to hook into, so the spot joins the tile's children.
    extend('ext:flarum/tags/forum/components/TagsPage', 'tagTileView', function (vnode, tag) {
      if (vnode && Array.isArray(vnode.children)) {
        vnode.children.push(m(HidingSpot, {
          spot: "tags.tile",
          className: "HidingSpot-tagTile",
          context: ['tag', Number(tag.id())]
        }));
      }
    });
  }

  // The search window is loaded on demand, so its spot is looked up the first time search is opened on a page.
  extend('flarum/common/components/SearchModal', 'activeTabItems', function (items) {
    items.add('scavengerHuntSpot', m(HidingSpot, {
      spot: "search.modal",
      className: "HidingSpot-searchModal"
    }), -1000);
  });

  // Core's Footer renders nothing; it is mounted on every page, so it hosts the footer and corner spots.
  override(Footer.prototype, 'view', function (original) {
    return [original(), m(HidingSpot, {
      spot: "page.footer",
      className: "HidingSpot-footer"
    }), m("div", {
      className: "ScavengerCorner"
    }, m(HidingSpot, {
      spot: "page.corner"
    }))];
  });
  extend('flarum/forum/components/UserPage', 'navItems', function (items) {
    if (this.user) {
      items.add('scavengerHuntTrophies', m(LinkButton, {
        href: app.route('fof-scavenger-hunt.user.trophies', {
          username: this.user.slug()
        }),
        icon: "fas fa-trophy"
      }, app.translator.trans('fof-scavenger-hunt.forum.trophies.nav')), 50);
    }
  });
  extend('flarum/forum/components/NotificationGrid', 'notificationTypes', function (items) {
    items.add('scavengerHuntCompleted', {
      name: 'scavengerHuntCompleted',
      icon: 'fas fa-trophy',
      label: app.translator.trans('fof-scavenger-hunt.forum.settings.notify_hunt_completed')
    });
  });
  if (activeHunts().length) {
    app.prefetch.add('fof-scavenger-hunt.collection', () => import(/* webpackChunkName: 'forum/components/CollectionModal', webpackMode: 'lazy-once' */ './components/CollectionModal'));
  }

  // "Hide it here" survives reloads for the manager who left it on.
  const saved = placement.saved();
  if (saved && canManageHunts()) {
    placement.start(saved);
  }
});flarum.reg.addChunkModule('559', '2819', 'fof-scavenger-hunt', 'forum/components/CollectionModal');
flarum.reg.addChunkModule('559', '2819', 'fof-scavenger-hunt', 'forum/components/CollectableCanvas');
flarum.reg.addChunkModule('559', '2819', 'fof-scavenger-hunt', 'forum/components/CollectionView');