import app from 'flarum/forum/app';
import Notification from 'flarum/forum/components/Notification';
import huntUrl from '../utils/huntUrl';
export default class HuntCompletedNotification extends Notification {
  icon() {
    return 'fas fa-trophy';
  }
  href() {
    const hunt = this.attrs.notification.subject();
    return hunt ? huntUrl(hunt.slug()) ?? '' : '';
  }
  content() {
    const hunt = this.attrs.notification.subject();
    return app.translator.trans('fof-scavenger-hunt.forum.notifications.hunt_completed', {
      hunt: hunt ? hunt.title() : ''
    });
  }
  excerpt() {
    return null;
  }
}
flarum.reg.add('fof-scavenger-hunt', 'forum/components/HuntCompletedNotification', HuntCompletedNotification);