import Model from 'flarum/common/Model';
export default class Completion extends Model {
  completedAt() {
    return Model.attribute('completedAt', Model.transformDate).call(this);
  }
  position() {
    return Model.attribute('position').call(this);
  }
  user() {
    return Model.hasOne('user').call(this);
  }
  hunt() {
    return Model.hasOne('hunt').call(this);
  }
}
flarum.reg.add('fof-scavenger-hunt', 'common/models/Completion', Completion);