import app from 'flarum/forum/app';
/**
 * The actor's visible, running Hunts from the forum payload. It never says where a Part is.
 */
export function activeHunts() {
  return app.forum?.attribute('scavengerHunts') ?? [];
}
export function canManageHunts() {
  return !!app.forum?.attribute('scavengerHuntCanManage');
}

/**
 * Keeps the payload's progress in step after a claim, so the header indicator updates without a reload.
 */
export function updateProgress(huntId, foundCount) {
  const hunt = activeHunts().find(candidate => candidate.id === huntId);
  if (hunt) {
    hunt.foundCount = foundCount;
  }
}
flarum.reg.add('fof-scavenger-hunt', 'forum/utils/activeHunts', { activeHunts: activeHunts,canManageHunts: canManageHunts,updateProgress: updateProgress, });