import Model from 'flarum/common/Model';
export default class Encounter extends Model {
  spot() {
    return Model.attribute('spot').call(this);
  }
  contextType() {
    return Model.attribute('contextType').call(this);
  }
  contextId() {
    return Model.attribute('contextId').call(this);
  }

  /**
   * Null for actors who may see the Part but not claim it: guests and, by default, Hunt managers.
   */
  token() {
    return Model.attribute('token').call(this);
  }
  expiresAt() {
    return Model.attribute('expiresAt', Model.transformDate).call(this);
  }
  part() {
    return Model.hasOne('part').call(this);
  }
}
flarum.reg.add('fof-scavenger-hunt', 'common/models/Encounter', Encounter);